import { BaseException, WindowUnhandledException } from '@game-studio/exceptions';
import { ILogger, ILoggerOptions, IProvider, LogLevel } from './types';

export class Logger implements ILogger {
    protected providers: IProvider[] = [];
    protected logLevel: LogLevel;
    protected locale: string;
    protected operator: string;

    constructor(options: ILoggerOptions) {
        this.logLevel = options.logLevel || LogLevel.DEBUG;
        window.onerror = this.handleGlobalError.bind(this);
        this.locale = options.locale;
        this.operator = options.operator;
        this.setProviders(options.providers);
    }

    public setProviders(providers: IProvider[]): void {
        this.providers.forEach((provider) => provider.cancelSchedule());
        this.providers = providers;
        this.providers.forEach((provider) => provider.setLocale(this.locale));
        this.providers.forEach((provider) => provider.setOperator(this.operator));
        this.providers.forEach((provider) => provider.startSchedule());
    }

    public error(error: BaseException, logToServer: boolean = true): void {
        if (this.logLevel >= LogLevel.ERROR) {
            this.providers.forEach((provider: IProvider) => provider.error(error.serialise(), logToServer));
        }
    }

    public warn<T extends object | void>(name: string, message: string, data?: T): void {
        if (this.logLevel >= LogLevel.WARN) {
            this.providers.forEach((provider: IProvider) => provider.warn(name, message, data));
        }
    }

    public info<T extends object | void>(name: string, message: string, data?: T): void {
        if (this.logLevel >= LogLevel.INFO) {
            this.providers.forEach((provider: IProvider) => provider.info(name, message, data));
        }
    }

    public debug<T extends object | void>(name: string, message: string, data?: T): void {
        if (this.logLevel >= LogLevel.DEBUG) {
            this.providers.forEach((provider: IProvider) => provider.debug(name, message, data));
        }
    }

    private handleGlobalError(message: string | Event, filename?: string, lineno?: number, colno?: number, error?: Error): void {
        if (error) {
            this.error(new WindowUnhandledException(error.message, error.data, error.stack), true);
        } else {
            this.error(new WindowUnhandledException(typeof message === 'string' ? message : ''), true);
        }
    }
}
